// Generated by collaboration-service (`npm run contract:generate`). Do not edit.
// The room contract lives in collaboration-service under src/contract/.

/**
 * Version of the room contract (state definition and message types).
 * Raise it whenever a change to the contract breaks older frontends.
 */
export const CONTRACT_VERSION = 1;

/** The name under which the Room type is registered. */
export const ROOM_NAME = "collaboration";

/** The options a client passes when creating or joining a Room. */
export type JoinOptions = {
  /** The client's CONTRACT_VERSION. */
  contractVersion: number;
  /** The display name, typed by the person. Ignored while login is on: the name then comes from the login. */
  name: string;
  /**
   * Only when creating: the creator's own exploration, which becomes the
   * Room's. Each capability adds its part.
   */
  startingState?: StartingState;
};

/** The creator's own exploration, handed over to a new Room. */
export type StartingState = {
  /** The value of the Landscape token being explored. */
  landscapeToken?: string;
  /** The closed and hidden Districts. */
  districts?: DistrictLists;
  /** The ids of the highlighted entities; they become the creator's highlights. */
  highlights?: string[];
};

/**
 * Error codes with which the service refuses to create or join a Room.
 * The SDK rejects `create` / `joinById` with an error carrying the code.
 */
export const JoinRefusal = {
  /** No live Room has this code (Colyseus' own code). */
  UNKNOWN_ROOM: 522,
  /** The client was built against another CONTRACT_VERSION. */
  CONTRACT_MISMATCH: 4100,
  /** The Room already has its maximum number of Participants. */
  ROOM_FULL: 4101,
  /** Login is on and the request carried no valid login token. */
  LOGIN_REQUIRED: 4102,
} as const;

/**
 * Close codes with which the service removes a Participant from a Room.
 * The SDK passes the code to `room.onLeave`. A removed Participant must not
 * be offered reconnection.
 */
export const LeaveCode = {
  /** The Host kicked the Participant. They may rejoin with the room code. */
  KICKED: 4011,
} as const;

/** A Room keeps this many chat entries; the oldest are dropped beyond that. */
export const CHAT_HISTORY_LIMIT = 200;

/** The longest chat message, in characters, after trimming. */
export const MAX_CHAT_MESSAGE_LENGTH = 1000;

/**
 * What a chat entry is. Participants post messages; the service writes
 * entries of other kinds itself (e.g. ping and highlight events).
 */
export const ChatEntryKind = {
  /** A message a Participant posted. */
  MESSAGE: "message",
} as const;
export type ChatEntryKind = (typeof ChatEntryKind)[keyof typeof ChatEntryKind];

/**
 * Reasons with which the service rejects a chat request. The SDK rejects
 * `room.request(...)` with an error whose `reason` is one of these.
 */
export const ChatRefusal = {
  /** The sender is muted by the Host. */
  MUTED: "muted",
  /** Only the Host (or, for deletion, the author) may do this. */
  NOT_ALLOWED: "not_allowed",
  /** The payload is malformed, empty, too long, or names nothing known. */
  INVALID: "invalid",
} as const;
export type ChatRefusal = (typeof ChatRefusal)[keyof typeof ChatRefusal];

/**
 * One change to the closed and hidden Districts. A user action (a click)
 * becomes one list of these, sent as one "districts" message and applied as a
 * whole, so two Participants acting at once never interleave.
 *
 * Which Districts a click concerns (children, nested ones, a whole city) is
 * worked out by the frontend, which knows the Landscape; the service does not.
 * "Close all" is a close of every District, a hide of the nested ones and a
 * show of the top-level ones.
 */
export type DistrictAction =
  | { type: "open"; ids: string[] }
  | { type: "close"; ids: string[] }
  | { type: "show"; ids: string[] }
  | { type: "hide"; ids: string[] }
  /** Opens and shows every District. */
  | { type: "openAll" };

/** The closed and hidden Districts as plain lists of District ids. */
export type DistrictLists = { closed: string[]; hidden: string[] };

/**
 * The Host's switch of the District sharing option. Switching it off changes
 * nobody's view: everyone takes the Room's Districts as their own. Switching
 * it on makes the Host's own Districts the Room's, so it carries them.
 */
export type DistrictSharing =
  | { shared: false }
  | { shared: true; districts: DistrictLists };

/** What `applyDistrictActions` changes: a set of District ids. */
export type DistrictIdSet = {
  add(id: string): unknown;
  delete(id: string): unknown;
  clear(): void;
};

/**
 * The meaning of the District actions. The same function changes the
 * person's own Districts in the browser when alone and the Room's in the
 * service.
 */
export function applyDistrictActions(
  districts: { closed: DistrictIdSet; hidden: DistrictIdSet },
  actions: readonly DistrictAction[],
): void {
  for (const action of actions) {
    switch (action.type) {
      case "open":
        for (const id of action.ids) districts.closed.delete(id);
        break;
      case "close":
        for (const id of action.ids) districts.closed.add(id);
        break;
      case "show":
        for (const id of action.ids) districts.hidden.delete(id);
        break;
      case "hide":
        for (const id of action.ids) districts.hidden.add(id);
        break;
      case "openAll":
        districts.closed.clear();
        districts.hidden.clear();
        break;
    }
  }
}

/**
 * One user action on the highlights, sent as one "highlights" message. An
 * entity has at most one highlighter: highlighting an entity somebody else
 * highlighted takes it over. Removing touches only the actor's own highlights,
 * so removing another Participant's highlight takes two clicks.
 */
export type HighlightAction =
  /** The entity becomes the actor's highlight, whoever had it before. */
  | { type: "highlight"; entityId: string }
  /** The actor's highlight of the entity is removed; anyone else's stays. */
  | { type: "unhighlight"; entityId: string }
  /** A click: removes the actor's own highlight of the entity, else highlights it (taking it over). */
  | { type: "toggle"; entityId: string }
  /** Removes every highlight of the actor; everyone else's stay. */
  | { type: "unhighlightAll" };

/** The longest entity id the service accepts in a highlight action, so every action stays far below 4 KB. */
export const MAX_ENTITY_ID_LENGTH = 1000;

/** What `applyHighlightAction` changes: entity id -> the highlighter. */
export type HighlightOwners = {
  get(entityId: string): string | undefined;
  set(entityId: string, highlighter: string): unknown;
  delete(entityId: string): unknown;
  forEach(callback: (highlighter: string, entityId: string) => void): void;
};

/**
 * The meaning of a highlight action by `actor`. The same function changes the
 * person's own highlights in the browser when alone (where every highlight is
 * the person's) and the Room's in the service.
 */
export function applyHighlightAction(highlights: HighlightOwners, actor: string, action: HighlightAction): void {
  switch (action.type) {
    case "highlight":
      highlights.set(action.entityId, actor);
      break;
    case "unhighlight":
      if (highlights.get(action.entityId) === actor) highlights.delete(action.entityId);
      break;
    case "toggle":
      if (highlights.get(action.entityId) === actor) highlights.delete(action.entityId);
      else highlights.set(action.entityId, actor);
      break;
    case "unhighlightAll": {
      const own: string[] = [];
      highlights.forEach((highlighter, entityId) => {
        if (highlighter === actor) own.push(entityId);
      });
      for (const entityId of own) highlights.delete(entityId);
      break;
    }
  }
}

/**
 * Messages a client sends to the Room: message type -> payload.
 * Each entry has a handler of the same name in CollaborationRoom's `messages`.
 */
export type ClientMessages = {
  /** Host only: removes the Participant with this session id from the Room. */
  kick: { sessionId: string };
  /** Host only: makes the Participant with this session id the Host instead. */
  handOverHost: { sessionId: string };
  /** Changes the sender's own color to a CSS hex color such as "#e6194b". Other values are ignored. */
  setColor: { color: string };
  /** Post a chat message. Rejected with a ChatRefusal (e.g. "muted"). */
  chatSend: { text: string };
  /** Delete a chat entry for everyone. Allowed for its author and the Host. */
  chatDelete: { entryId: string };
  /** Mute or unmute a Participant (by session id). Host only. */
  chatMute: { participantId: string; muted: boolean };
  /** Follow another Participant's camera (their session id), or stop with null. */
  spectate: { target: string | null };
  /**
   * The sender's camera, sent only while somebody spectates them, at most
   * CAMERA_UPDATES_PER_SECOND times per second and only when it changed.
   */
  camera: CameraPose;
  /** The sender entered the immersive view of this entity, or left it with null. */
  immersive: { entityId: string | null };
  /**
   * Host only: the Room explores this Landscape (a Landscape token value)
   * from now on. Clears everything tied to the old Landscape.
   */
  switchLandscape: { landscapeToken: string };
  /** One user action on the Districts (see DistrictAction). */
  districts: DistrictAction[];
  /** Host only: switches the District sharing option (see DistrictSharing). */
  districtSharing: DistrictSharing;
  /** One user action on the highlights (see HighlightAction). */
  highlights: HighlightAction;
};

/**
 * Messages the Room sends to clients: message type -> payload.
 */
export type ServerMessages = {
  /** The camera of the Participant `from`, forwarded only to those who spectate them. */
  camera: CameraPose & { from: string };
};

/** A camera as world-space pose plus the column-major 4x4 projection matrix (as three.js `toArray()`). */
export type CameraPose = {
  position: [number, number, number];
  quaternion: [number, number, number, number];
  projection: number[];
};

/** How often a spectated Participant sends its camera at most. */
export const CAMERA_UPDATES_PER_SECOND = 30;

// Room state, as plain snapshot types.

export type CollaborationState = {
  participants: Record<string, Participant>;
  hostId: string;
  landscapeToken: string;
  chat: ChatEntry[];
  districts: Districts;
  highlights: Record<string, string>;
};

export type Participant = {
  name: string;
  color: string;
  muted: boolean;
  spectating: string;
  immersiveEntityId: string;
};

export type ChatEntry = {
  id: string;
  kind: string;
  authorId: string;
  authorName: string;
  authorColor: string;
  text: string;
  time: number;
};

export type Districts = {
  shared: boolean;
  closed: Record<string, boolean>;
  hidden: Record<string, boolean>;
};
